<?php defined('ALTUMCODE') || die();
$learningRecords=fcc_coach_knowledge()['records'];
foreach($learningRecords as &$record)foreach(['title','summary','example','team_question','source_section'] as $field)if(isset($record[$field]))$record[$field]=fcc_t($record[$field]);unset($record);
$topicKey=is_string($_GET['topic']??null)?$_GET['topic']:'forever_fcc';
$learningRecord=$learningRecords[0];foreach($learningRecords as $record)if($record['topic_id']===$topicKey)$learningRecord=$record;
$learningQuestion=$learningRecord['team_question'];
$learningContacts=fcc_education_contacts((int)$this->user->user_id,$learningRecord['title']);
foreach($learningContacts as &$person){if($person['url']){$phone=parse_url($person['url'],PHP_URL_PATH);$person['url']='https://wa.me/'.trim($phone,'/').'?text='.rawurlencode($learningQuestion);}}unset($person);
?>
